 static class MutableClock extends Clock{Instant value=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId ignored){return this;}public Instant instant(){return value;}void advance(long seconds){value=value.plusSeconds(seconds);}}
 private JdbcTemplate jdbc,admin;private org.springframework.transaction.PlatformTransactionManager manager;private AuditWriter audit;private MutableClock clock;private SimpleMeterRegistry metrics;private CarrierBookingExecution execution;private CarrierContextClient source;private CarrierShipmentRequest requests;private CarrierProvider provider;private HttpServer server;
 private final UUID shipment=UUID.randomUUID(),reference=UUID.randomUUID(),generation=UUID.randomUUID(),correlation=UUID.randomUUID();private final AtomicInteger writes=new AtomicInteger(),reads=new AtomicInteger(),polls=new AtomicInteger();private final AtomicReference<String> violation=new AtomicReference<>();private volatile String scenario="sync";private volatile boolean ready=true,contextAllowed=true;private UUID job,booking;private software.amazon.awssdk.services.s3.S3Client labelClient;private JsonNode storageConfig;private String encodedLabel;private final AtomicInteger acknowledgements=new AtomicInteger();private String acceptedAck;private JsonNode acceptedResponse;
 @BeforeEach void setup()throws Exception{
  String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native isolated owned PostgreSQL required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_INTEGRATION_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=integration","nigson_integration_app","mock-integration-runtime");jdbc=new JdbcTemplate(ds);admin=new JdbcTemplate(new DriverManagerDataSource(url,"nigson_bootstrap","mock-bootstrap"));manager=new DataSourceTransactionManager(ds);clock=new MutableClock();metrics=new SimpleMeterRegistry();audit=new AuditWriter(jdbc,clock,metrics);try(var document=new org.apache.pdfbox.pdmodel.PDDocument();var sink=new java.io.ByteArrayOutputStream()){document.addPage(new org.apache.pdfbox.pdmodel.PDPage(new org.apache.pdfbox.pdmodel.common.PDRectangle(288,432)));document.save(sink);encodedLabel=Base64.getEncoder().encodeToString(sink.toByteArray());}server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/",e->{String path=e.getRequestURI().getPath();byte[] bytes=e.getRequestBody().readAllBytes();Object response;int status=200;try{
   if(path.endsWith("/provider-context")){reads.incrementAndGet();if(!"Bearer synthetic-workload".equals(e.getRequestHeaders().getFirst("Authorization")))violation.set("SOURCE_AUTH");if(contextAllowed)response=context();else{status=409;response=Map.of("code","INVALID_TRANSITION");}}
   else if(path.endsWith("/provider-result")){acknowledgements.incrementAndGet();String sent=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);if(acceptedAck!=null&&!acceptedAck.equals(sent))violation.set("ACK_BODY_CHANGED");if(acceptedAck==null){var ack=EventCodec.JSON.readTree(bytes);var head=labelClient.headObject(software.amazon.awssdk.services.s3.model.HeadObjectRequest.builder().bucket(storageConfig.path("buckets").path(2).asString()).key(ack.path("labelObjectKey").asString()).checksumMode(software.amazon.awssdk.services.s3.model.ChecksumMode.ENABLED).build());if(!reference.toString().equals(head.metadata().get("owner"))||!ack.path("labelChecksum").asString().equals(HexFormat.of().formatHex(Base64.getDecoder().decode(head.checksumSHA256()))))violation.set("ACK_LABEL_PROOF");acceptedAck=sent;var view=EventCodec.JSON.createObjectNode().put("id",shipment.toString()).put("orderId",UUID.randomUUID().toString()).put("status","READY").put("version",1);view.putNull("trackingUrl");view.set("lines",EventCodec.JSON.valueToTree(List.of(Map.of("orderLineId",UUID.randomUUID(),"quantity","1"))));acceptedResponse=view;if(scenario.equals("lost-ack")){e.sendResponseHeaders(200,100);e.getResponseBody().write('{');e.close();return;}}response=acceptedResponse;}
   else if(path.equals("/oauth/token"))response=Map.of("access_token","mock-execution-token","token_type","bearer","expires_in",3600);
   else if(path.equals("/ship/v1/shipments")){writes.incrementAndGet();var input=EventCodec.JSON.readTree(bytes);if(!"mock-execution-account".equals(input.path("accountNumber").path("value").asString()))violation.set("ACCOUNT");var row=jdbc.queryForMap("SELECT b.request_hash,j.cursor::text AS checkpoint FROM integration.carrier_booking b JOIN integration.integration_job j ON j.business_key=b.business_key WHERE b.shipment_id=?",shipment);var cursor=EventCodec.JSON.readTree(row.get("checkpoint").toString());if(!"PREPARED".equals(cursor.path("stage").asString())||!row.get("request_hash").equals(cursor.path("requestHash").asString()))violation.set("INTENT_NOT_COMMITTED");new TransactionTemplate(manager).execute(s->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.queryForMap("SELECT id FROM integration.carrier_booking WHERE shipment_id=? FOR UPDATE",shipment);return null;});
    if(scenario.equals("lost")){e.sendResponseHeaders(200,100);e.getResponseBody().write('{');e.close();return;}response=scenario.equals("async")?Map.of("output",Map.of("jobId","synthetic-async-1")):Map.of("output",result());
   }else if(path.equals("/ship/v1/shipments/results")){polls.incrementAndGet();response=Map.of("output",ready?result():Map.of("transactionShipments",List.of()));}
   else if(path.equals("/track/v1/referencenumbers")){var input=EventCodec.JSON.readTree(bytes);if(!reference.toString().equals(input.path("referencesInformation").path("value").asString()))violation.set("REFERENCE");response=Map.of("output",Map.of("completeTrackResults",List.of(Map.of("trackingNumberInfo",Map.of("trackingNumber","123456789012")))));}
   else{status=404;response=Map.of("code","UNKNOWN_ROUTE");}
  }catch(Exception failure){violation.set("HTTP_TRANSACTION_PROOF_FAILED");status=500;response=Map.of("code","FIXTURE_FAILURE");}byte[] output=EventCodec.JSON.writeValueAsBytes(response);e.getResponseHeaders().set("Content-Type","application/json");try{e.sendResponseHeaders(status,output.length);try(var out=e.getResponseBody()){out.write(output);}}catch(java.io.IOException cancelled){e.close();}});server.start();String base="http://127.0.0.1:"+server.getAddress().getPort();provider=new FedExAdapter("test",ProviderHttp.Mode.MOCK,base,"mock-execution-client","mock-execution-secret","mock-execution-account");source=new CarrierContextClient("test",base,r->"synthetic-workload");requests=new CarrierShipmentRequest(Set.of("SYNTHETIC_SERVICE"),"DROPOFF_AT_FEDEX_LOCATION","PAPER_4X6","SENDER","synthetic-offline-approval",clock.instant().plusSeconds(3600),clock);execution=execution(provider.accountFingerprint(),generation);
  var event=(ObjectNode)EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(System.getenv("NIGSON_EVENT_FIXTURES"),"shipment.booking.requested.v1.json")));event.put("occurred_at",clock.instant().toString()).put("event_id",UUID.randomUUID().toString()).put("aggregate_id",shipment.toString()).put("correlation_id",correlation.toString());((ObjectNode)event.get("payload")).put("shipment_id",shipment.toString()).put("booking_request_id",reference.toString());var handler=new CarrierBookingRequestedHandler(new JdbcJobRepository(jdbc,clock),audit,clock,provider.mode(),generation,provider.accountFingerprint());new PlatformStore(jdbc,manager,clock,metrics).consume("synthetic-carrier-execution",EventCodec.JSON.writeValueAsString(event),1,handler::handle);job=jdbc.queryForObject("SELECT id FROM integration.integration_job WHERE business_key=?",UUID.class,"carrier-booking:"+reference);booking=jdbc.queryForObject("SELECT id FROM integration.carrier_booking WHERE shipment_id=?",UUID.class,shipment);
 }
 @AfterEach void cleanup(){if(server!=null)server.stop(0);if(labelClient!=null)labelClient.close();if(jdbc!=null){jdbc.update("DELETE FROM integration.carrier_booking WHERE shipment_id=?",shipment);jdbc.update("DELETE FROM integration.integration_job WHERE id=?",job);}assertThat(violation.get()).isNull();}
 private CarrierBookingExecution execution(String account,UUID epoch){return new CarrierBookingExecution(jdbc,manager,audit,clock,ProviderHttp.Mode.MOCK,account,epoch,Instant.EPOCH,metrics);}
 private Map<String,Object> context(){var address=new CarrierValues.Address("Synthetic Recipient","+2348000000001","Synthetic Street",null,"Lagos","LA",null,"NG");var destination=(ObjectNode)EventCodec.JSON.valueToTree(address);destination.put("label","Synthetic saved").put("isDefault",false);return Map.of("shipmentId",shipment,"orderId",UUID.randomUUID(),"address",destination,"shipper",address,"serviceCode","SYNTHETIC_SERVICE","packages",List.of(new CarrierValues.Parcel(UUID.randomUUID(),"1","1.2","10","10","10")),"bookingReference",reference,"mode","MOCK");}
 private JsonNode result(){return EventCodec.JSON.valueToTree(Map.of("transactionShipments",List.of(Map.of("masterTrackingNumber","123456789012","pieceResponses",List.of(Map.of("trackingNumber","123456789012","packageDocuments",List.of(Map.of("contentType","LABEL","docType","PDF","encodedLabel",encodedLabel))))))));}
 private CarrierBookingExecution.Claim claim(){return execution.claim(shipment).orElseThrow();}
 private CarrierBookingExecution.Claim prepared(CarrierBookingExecution.Claim claim){var context=CarrierCreationContext.parse(EventCodec.JSON.valueToTree(context()),shipment,reference,provider.mode());return execution.prepare(claim,requests.build(context,LocalDate.now(clock)),clock.instant().plusSeconds(600)).orElseThrow();}
 private JsonNode checkpoint(){return EventCodec.JSON.readTree(jdbc.queryForObject("SELECT cursor::text FROM integration.integration_job WHERE id=?",String.class,job));}
 @Test void twelveWorkersClaimOnePairedLeaseAndFreshSubmissionCommitsBeforeProviderHttp()throws Exception{
  var results=new ArrayList<CarrierBookingExecution.Claim>();try(var pool=Executors.newFixedThreadPool(12)){var start=new CountDownLatch(1);var tasks=new ArrayList<Future<Optional<CarrierBookingExecution.Claim>>>();for(int i=0;i<12;i++)tasks.add(pool.submit(()->{start.await();return execution.claim(shipment);}));start.countDown();for(var task:tasks)task.get(15,TimeUnit.SECONDS).ifPresent(results::add);}assertThat(results).hasSize(1);var claim=results.getFirst();assertThat(claim.mayCreate()).isTrue();assertThat(claim.correlation()).isEqualTo(correlation);assertThat(Duration.between(clock.instant(),claim.lease())).isEqualTo(Duration.ofSeconds(120));var submitted=execution.submit(claim,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600));assertThat(submitted.persisted()).isTrue();assertThat(submitted.toString()).doesNotContain("transactionShipments");assertThat(writes.get()).isEqualTo(1);assertThat(reads.get()).isEqualTo(1);assertThat(checkpoint().path("stage").asString()).isEqualTo("LABEL_PENDING");assertThat(jdbc.queryForObject("SELECT state FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo("CLAIMED");assertThat(jdbc.queryForObject("SELECT label_object_key FROM integration.carrier_booking WHERE id=?",String.class,booking)).isNull();assertThat(execution.claim(shipment)).isEmpty();
 }
 @Test void expiredPreparationAndStaleWorkerCannotRebookOrOverwriteNewGeneration(){var prepared=prepared(claim());String hash=prepared.requestHash();clock.advance(121);assertThat(execution.acceptedAsync(prepared,"stale-job")).isFalse();var recovered=claim();assertThat(recovered.mayCreate()).isFalse();assertThat(recovered.requestHash()).isEqualTo(hash);assertThat(execution.unknown(prepared,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isFalse();assertThatThrownBy(()->execution.submit(recovered,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isZero();assertThat(reads.get()).isZero();assertThat(execution.unknown(recovered,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isTrue();assertThat(jdbc.queryForObject("SELECT state FROM integration.integration_job WHERE id=?",String.class,job)).isEqualTo("UNKNOWN");}
 @Test void changedRestoreGenerationAndLegacyCheckpointNeverGainCreatePermission(){var changed=execution(provider.accountFingerprint(),UUID.randomUUID());var restored=changed.claim(shipment).orElseThrow();assertThat(restored.compatible()).isTrue();assertThat(restored.mayCreate()).isFalse();assertThat(changed.unknown(restored,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isTrue();clock.advance(31);jdbc.update("UPDATE integration.integration_job SET cursor='{}'::jsonb WHERE id=?",job);var legacy=claim();assertThat(legacy.mayCreate()).isFalse();assertThat(legacy.compatible()).isFalse();assertThatThrownBy(()->prepared(legacy)).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isZero();}
 @Test void accountIdentityChangeCannotPrepareOrSubmit(){var changed=execution("b".repeat(64),generation);var claim=changed.claim(shipment).orElseThrow();assertThat(claim.compatible()).isFalse();assertThat(claim.mayCreate()).isFalse();assertThatThrownBy(()->changed.submit(claim,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isZero();assertThat(reads.get()).isZero();}
 @Test void preparationAndAcceptanceRollbackBothRowsWhenAuditFails(){var claim=claim();String hash=claim.requestHash();admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThatThrownBy(()->prepared(claim)).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}assertThat(checkpoint().path("stage").asString()).isEqualTo("INTENT");assertThat(jdbc.queryForObject("SELECT request_hash FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo(hash);var prepared=prepared(claim);admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThatThrownBy(()->execution.acceptedAsync(prepared,"synthetic-async-1")).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}assertThat(checkpoint().path("stage").asString()).isEqualTo("PREPARED");assertThat(jdbc.queryForObject("SELECT provider_shipment_id FROM integration.carrier_booking WHERE id=?",String.class,booking)).isNull();assertThat(execution.acceptedAsync(prepared,"synthetic-async-1")).isTrue();}
 @Test void acceptedAsyncJobRetrievesReadOnlyAfterPendingResultWithoutCreationContext(){scenario="async";ready=false;var submitted=execution.submit(claim(),source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600));assertThat(submitted.persisted()).isTrue();assertThat(checkpoint().path("stage").asString()).isEqualTo("ASYNC");contextAllowed=false;clock.advance(31);var pending=claim();assertThat(pending.mayCreate()).isFalse();assertThatThrownBy(()->execution.retrieve(pending,provider)).isInstanceOf(Problem.Failure.class);assertThat(checkpoint().path("asyncJobId").asString()).isEqualTo("synthetic-async-1");ready=true;clock.advance(31);assertThat(execution.retrieve(claim(),provider).persisted()).isTrue();assertThat(checkpoint().path("stage").asString()).isEqualTo("LABEL_PENDING");assertThat(writes.get()).isEqualTo(1);assertThat(polls.get()).isEqualTo(2);assertThat(reads.get()).isEqualTo(1);}
 @Test void lostResponseAfterAcceptanceRemainsUnknownAndReferenceLookupNeverRecreates(){scenario="lost";assertThatThrownBy(()->execution.submit(claim(),source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT state FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo("UNKNOWN");clock.advance(31);var recovered=claim();assertThat(recovered.mayCreate()).isFalse();var result=provider.trackReference(reference.toString(),LocalDate.now(clock),LocalDate.now(clock));assertThat(result.path("completeTrackResults").path(0).path("trackingNumberInfo").path("trackingNumber").asString()).isEqualTo("123456789012");assertThatThrownBy(()->execution.submit(recovered,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isEqualTo(1);}
 @Test void sourceRejectsAlreadyBookedContextBeforeAnyProviderWrite(){contextAllowed=false;assertThatThrownBy(()->execution.submit(claim(),source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOfSatisfying(Problem.Failure.class,f->assertThat(f.code).isEqualTo(ProblemCode.INVALID_TRANSITION));assertThat(writes.get()).isZero();assertThat(jdbc.queryForObject("SELECT state FROM integration.integration_job WHERE id=?",String.class,job)).isEqualTo("UNKNOWN");}
 @Test void expiredQualificationAndWrongBusinessReferenceCannotPrepare(){var claimed=claim();var context=CarrierCreationContext.parse(EventCodec.JSON.valueToTree(context()),shipment,reference,provider.mode());var request=requests.build(context,LocalDate.now(clock));assertThatThrownBy(()->execution.prepare(claimed,request,clock.instant())).isInstanceOf(Problem.Failure.class);((ObjectNode)request.path("requestedShipment").path("requestedPackageLineItems").path(0).path("customerReferences").path(0)).put("value",UUID.randomUUID().toString());assertThatThrownBy(()->execution.prepare(claimed,request,clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(checkpoint().path("stage").asString()).isEqualTo("INTENT");assertThat(writes.get()).isZero();}
 @Test void malformedPieceSetCannotMarkAcceptanceOrLeakCheckpointValues(){var prepared=prepared(claim());var output=(ObjectNode)result();((ObjectNode)output.path("transactionShipments").path(0).path("pieceResponses").path(0)).put("trackingNumber","999999999999");assertThatThrownBy(()->execution.acceptedShipment(prepared,output)).isInstanceOf(Problem.Failure.class);assertThat(checkpoint().path("stage").asString()).isEqualTo("PREPARED");var copied=(ObjectNode)prepared.checkpoint();copied.put("stage","INTENT");assertThat(prepared.checkpoint().path("stage").asString()).isEqualTo("PREPARED");assertThat(prepared.toString()).isEqualTo("CarrierExecutionClaim[protected]");}

 private CarrierBookingWorker worker()throws Exception{String path=System.getenv("NIGSON_TEST_CARRIER_STORAGE_FIXTURE");Assumptions.assumeTrue(path!=null,"isolated TLS/SigV4 label fixture required");storageConfig=EventCodec.JSON.readTree(java.nio.file.Files.readString(java.nio.file.Path.of(path)));var env=new org.springframework.mock.env.MockEnvironment().withProperty("APP_ENV","test").withProperty("NIGSON_SECURITY_ENABLED","true").withProperty("NIGSON_AWS_REGION",storageConfig.path("region").asString()).withProperty("NIGSON_S3_LOCAL_ENDPOINT",storageConfig.path("endpoint").asString()).withProperty("NIGSON_S3_LOCAL_CA",storageConfig.path("ca").asString()).withProperty("NIGSON_S3_PRIVATE_BUCKET",storageConfig.path("buckets").path(2).asString());var factory=new CarrierLabelConfiguration();labelClient=factory.carrierLabelClient(env);var labels=factory.carrierLabelStorage(labelClient,env);return new CarrierBookingWorker(execution,source,requests,provider,labels,clock,clock.instant().plusSeconds(600));}
 @Test void fullWorkerCreatesPrivatePdfAndAcknowledgesSourceBeforeCompletingJob()throws Exception{var worker=worker();assertThat(worker.process(claim())).isEqualTo(1);assertThat(writes.get()).isEqualTo(1);assertThat(reads.get()).isEqualTo(1);assertThat(acknowledgements.get()).isEqualTo(1);assertThat(checkpoint().path("stage").asString()).isEqualTo("COMPLETE");assertThat(jdbc.queryForObject("SELECT state FROM integration.integration_job WHERE id=?",String.class,job)).isEqualTo("SUCCEEDED");assertThat(jdbc.queryForObject("SELECT state FROM integration.carrier_booking WHERE id=?",String.class,booking)).isEqualTo("BOOKED");assertThat(execution.claim(shipment)).isEmpty();}
 @Test void lostSourceAckReplaysExactBodyWithoutRebookingUploadingOrRefetchingContext()throws Exception{scenario="lost-ack";var worker=worker();worker.process(claim());assertThat(checkpoint().path("stage").asString()).isEqualTo("ACK");assertThat(jdbc.queryForObject("SELECT state FROM integration.integration_job WHERE id=?",String.class,job)).isEqualTo("UNKNOWN");String frozen=EventCodec.JSON.writeValueAsString(checkpoint().path("ack"));contextAllowed=false;clock.advance(31);worker.process(claim());assertThat(EventCodec.JSON.writeValueAsString(checkpoint().path("ack"))).isEqualTo(frozen);assertThat(checkpoint().path("stage").asString()).isEqualTo("COMPLETE");assertThat(writes.get()).isEqualTo(1);assertThat(reads.get()).isEqualTo(1);assertThat(acknowledgements.get()).isEqualTo(2);}
 @Test void crashAfterUploadRecoversPinnedObjectBeforeAckWithoutNewProviderWrite()throws Exception{var worker=worker();var submitted=execution.submit(claim(),source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600));var active=submitted.claim();var label=CarrierLabelCodec.decode(submitted.output(),"123456789012",1);var store=new CarrierLabelStorage(labelClient,"test",storageConfig.path("buckets").path(2).asString(),"");var uploading=execution.labelIntent(active,store.key(shipment),label.checksum(),label.bytes().length).orElseThrow();assertThat(checkpoint().path("stage").asString()).isEqualTo("UPLOAD");var object=store.store(shipment,reference,label);clock.advance(121);contextAllowed=false;worker.process(claim());assertThat(checkpoint().path("stage").asString()).isEqualTo("COMPLETE");assertThat(labelClient.headObject(r->r.bucket(storageConfig.path("buckets").path(2).asString()).key(object.key())).versionId()).isEqualTo(object.version());assertThat(writes.get()).isEqualTo(1);assertThat(reads.get()).isEqualTo(1);assertThat(acknowledgements.get()).isEqualTo(1);assertThat(execution.unknown(uploading,ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).isFalse();}

 @Test void replayedPreRestoreOutboxEventCannotMintFreshPermissionAfterRowsAreLost(){execution.submit(claim(),source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600));assertThat(writes.get()).isEqualTo(1);clock.advance(3600);jdbc.update("DELETE FROM integration.carrier_booking WHERE id=?",booking);jdbc.update("DELETE FROM integration.integration_job WHERE id=?",job);var restoredEpoch=UUID.randomUUID();var event=EventCodec.JSON.createObjectNode().put("event_id",UUID.randomUUID().toString()).put("event_type","shipment.booking.requested.v1").put("schema_version",1).put("producer","commerce").put("occurred_at",clock.instant().minusSeconds(3600).toString()).put("aggregate_id",shipment.toString()).put("aggregate_version",1).put("correlation_id",correlation.toString());event.putNull("organization_id");event.putNull("traceparent");event.set("payload",EventCodec.JSON.valueToTree(Map.of("shipment_id",shipment,"booking_request_id",reference,"provider","FEDEX")));var intake=new CarrierBookingRequestedHandler(new JdbcJobRepository(jdbc,clock),audit,clock,provider.mode(),restoredEpoch,provider.accountFingerprint());new PlatformStore(jdbc,manager,clock,metrics).consume("synthetic-restored-consumer",EventCodec.JSON.writeValueAsString(event),1,intake::handle);job=jdbc.queryForObject("SELECT id FROM integration.integration_job WHERE business_key=?",UUID.class,"carrier-booking:"+reference);booking=jdbc.queryForObject("SELECT id FROM integration.carrier_booking WHERE shipment_id=?",UUID.class,shipment);var restored=new CarrierBookingExecution(jdbc,manager,audit,clock,provider.mode(),provider.accountFingerprint(),restoredEpoch,clock.instant().minusSeconds(60),metrics);var claim=restored.claim(shipment).orElseThrow();assertThat(claim.compatible()).isTrue();assertThat(claim.mayCreate()).isFalse();assertThatThrownBy(()->restored.submit(claim,source,requests,provider,LocalDate.now(clock),clock.instant().plusSeconds(600))).isInstanceOf(Problem.Failure.class);assertThat(writes.get()).isEqualTo(1);assertThat(reads.get()).isEqualTo(1);}

